type ListServicePointsByBranchParams struct {
	OrganizationID int64 `json:"organization_id"`
	BranchID       int64 `json:"branch_id"`
}

func (q *Queries) ListServicePointsByBranch(ctx context.Context, arg ListServicePointsByBranchParams) ([]ServicePoint, error) {
	rows, err := q.db.Query(ctx, listServicePointsByBranch, arg.OrganizationID, arg.BranchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ServicePoint{}
	for rows.Next() {
		var i ServicePoint
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BranchID,
			&i.Type,
			&i.Name,
			&i.Description,
			&i.ExtraFee,
			&i.WorkingHours,
			&i.OnlineSelectable,
			&i.IsActive,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

